from typing import Any, Literal, Annotated
from pydantic import BaseModel, Discriminator
from fastapi import FastAPI, Body
from fastapi.testclient import TestClient

class Tag:
    def __init__(self, value):
        self.value = value
    def __repr__(self):
        return f"Tag({self.value})"

class Pie(BaseModel):
    time_to_cook: int
    num_ingredients: int

class ApplePie(Pie):
    fruit: Literal["apple"] = "apple"

class PumpkinPie(Pie):
    filling: Literal["pumpkin"] = "pumpkin"

def get_discriminator_value(v: Any) -> str:
    if isinstance(v, dict):
        return v.get("fruit", v.get("filling"))
    return getattr(v, "fruit", getattr(v, "filling", None))

Dessert = Annotated[
    Annotated[ApplePie, Tag("apple")] | Annotated[PumpkinPie, Tag("pumpkin")],
    Discriminator(get_discriminator_value),
]

app = FastAPI()

@app.post("/dessert")
async def dinner(dessert: Dessert) -> dict[str, Any]:
    return dessert.model_dump()

client = TestClient(app)

def test_dessert():
    # This should be a body parameter.
    # If FastAPI thinks it's a query parameter, it will fail to find it in the body
    # or it will expect it in the query string.
    response = client.post("/dessert", json={"fruit": "apple", "time_to_cook": 10, "num_ingredients": 2})
    print(f"Status code: {response.status_code}")
    print(f"Response body: {response.json()}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_dessert()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
